CREATE TABLE checkout_sagas (id VARCHAR(64) PRIMARY KEY,user_id VARCHAR(64) NOT NULL,request_json JSONB NOT NULL,request_hash CHAR(64) NOT NULL,idempotency_key VARCHAR(160) NOT NULL,status VARCHAR(32) NOT NULL,current_step VARCHAR(40) NOT NULL,reservation_id VARCHAR(64),order_id VARCHAR(64),promotion_redemption_id VARCHAR(64),payment_id VARCHAR(64),payment_status VARCHAR(32),payment_client_secret VARCHAR(500),shipment_id VARCHAR(64),subtotal_minor BIGINT,promotion_discount_minor BIGINT,shipping_minor BIGINT,tax_minor BIGINT,total_minor BIGINT,currency CHAR(3),last_error VARCHAR(1000),attempt INTEGER NOT NULL DEFAULT 0,version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,UNIQUE(user_id,idempotency_key));
CREATE TABLE checkout_saga_steps(id VARCHAR(64) PRIMARY KEY,checkout_id VARCHAR(64) NOT NULL REFERENCES checkout_sagas(id) ON DELETE CASCADE,step VARCHAR(40) NOT NULL,status VARCHAR(32) NOT NULL,request_json JSONB,response_json JSONB,error_message VARCHAR(1000),attempt INTEGER NOT NULL DEFAULT 1,started_at TIMESTAMPTZ NOT NULL,completed_at TIMESTAMPTZ,UNIQUE(checkout_id,step));
CREATE TABLE checkout_idempotency(id VARCHAR(64) PRIMARY KEY,user_id VARCHAR(64) NOT NULL,idempotency_key VARCHAR(160) NOT NULL,request_hash CHAR(64) NOT NULL,checkout_id VARCHAR(64) NOT NULL REFERENCES checkout_sagas(id),created_at TIMESTAMPTZ NOT NULL,UNIQUE(user_id,idempotency_key));
CREATE TABLE checkout_inbox_events(event_id VARCHAR(160) PRIMARY KEY,received_at TIMESTAMPTZ NOT NULL);
CREATE TABLE checkout_outbox_events(id VARCHAR(64) PRIMARY KEY,aggregate_id VARCHAR(64) NOT NULL,event_type VARCHAR(100) NOT NULL,schema_version INTEGER NOT NULL DEFAULT 1,occurred_at TIMESTAMPTZ NOT NULL,correlation_id VARCHAR(160) NOT NULL,payload_json JSONB NOT NULL,published_at TIMESTAMPTZ);
CREATE INDEX checkout_recovery_idx ON checkout_sagas(status,updated_at);
CREATE INDEX checkout_outbox_unpublished_idx ON checkout_outbox_events(published_at,occurred_at) WHERE published_at IS NULL;
